    /**
     * Text
     *
     * Full explanation; citations appear inline as [e_...].
     */
    text: string;
    /**
     * Citations
     *
     * Edge IDs cited; always a subset of the path.
     */
    citations: Array<string>;
    /**
     * Cached
     */
    cached: boolean;
    /**
     * Reading Grade
     *
     * Flesch-Kincaid grade of the text.
     */
