/**
 * Path
 */
export type Path = {
    /**
     * Path Id
     *
     * path_id(edge_ids): 'p_' + 16 hex chars.
     */
    path_id: string;
    /**
     * Steps
     */
    steps: Array<PathStep>;
    /**
     * Edge Ids
     *
     * Edge IDs in traversal order.
     */
    edge_ids: Array<string>;
    /**
     * Total Cost
     *
     * Sum of -log(confidence) over the edges.
     */
    total_cost: number;
    /**
     * Min Confidence
     *
     * Lowest edge confidence on the path.
     */
    min_confidence: number;
    min_confidence_level: ConfidenceLevel;
    /**
     * All Observed
     *
     * Every edge has origin 'observed'.
     */
    all_observed: boolean;
    /**
     * All Active
     *
     * Every edge has status 'active'.
     */
    all_active: boolean;
    /**
     * Supported
     *
     * Every edge passes the confidence threshold.
     */
    supported: boolean;
};

/**
 * PathFamily
 */
export type PathFamily = 'dna' | 'symptoms' | 'research' | 'all';

/**
 * PathResponse
 */
export type PathResponse = {
    status: PathStatus;
    /**
     * From Id
     */
    from_id: string;
    /**
     * To Id
     */
    to_id: string;
    family: PathFamily;
    /**
     * Threshold
     *
     * Confidence threshold used.
     */
    threshold?: number;
    /**
     * Paths
     *
     * Top-k supported paths.
     */
    paths?: Array<Path>;
    /**
     * Present when status is no_supported_route.
     */
    coverage?: CoverageReport | null;
};

/**
 * PathStatus
 */
export type PathStatus = 'ok' | 'no_supported_route';

/**
 * PathStep
 */
export type PathStep = {
    edge: Edge;
    /**
     * Node the step starts at (in traversal order).
     */
    from_node: Node;
    /**
     * Node the step ends at (in traversal order).
     */
    to_node: Node;
    /**
     * Reversed
     *
     * True when traversed against the stored edge direction.
     */
    reversed?: boolean;
};

